

function frameToResult(frame, providerId) {
  return { canonical: frame, providerId, latencyMs: 0, warnings: [] };
}

export class ClipPlayback {
  constructor(onFrame, options = {}) {
    this.onFrame = onFrame;
    this.rate = options.rate ?? 1;
    this.loop = options.loop ?? false;
    this.clip = null;
    this.providerId = "mediapipe";
    this.animId = 0;
    this.startClock = 0;
    this.pausedAtMs = null;
    this.cursor = 0;
    this.finished = false;
  }

  play(clip, providerId = "mediapipe") {
    this.stop();
    if (clip.frames.length === 0) return;
    this.clip = clip;
    this.providerId = providerId;
    this.cursor = 0;
    this.finished = false;
    this.startClock = performance.now();
    this.animId = requestAnimationFrame(this.tick);
  }

  pause() {
    if (!this.clip || this.pausedAtMs !== null) return;
    this.pausedAtMs = this.elapsedTargetMs();
    if (this.animId) { cancelAnimationFrame(this.animId); this.animId = 0; }
    this.emit(this.cursor);
  }

  resume() {
    if (!this.clip || this.pausedAtMs === null) return;
    this.startClock = performance.now() - this.pausedAtMs / this.rate;
    this.pausedAtMs = null;
    this.animId = requestAnimationFrame(this.tick);
  }

  stop() {
    if (this.animId) { cancelAnimationFrame(this.animId); this.animId = 0; }
    this.clip = null;
    this.pausedAtMs = null;
    this.cursor = 0;
    this.finished = false;
  }

  get isPlaying() { return this.clip !== null && this.pausedAtMs === null; }
  get isPaused() { return this.clip !== null && this.pausedAtMs !== null; }

  elapsedTargetMs() { return (performance.now() - this.startClock) * this.rate; }

  tick = () => {
    const clip = this.clip;
    if (!clip) return;
    this.animId = requestAnimationFrame(this.tick);
    const target = this.elapsedTargetMs();
    const frames = clip.frames;
    while (this.cursor < frames.length - 1 && frames[this.cursor + 1].timestamp <= target) {
      this.cursor++;
    }
    const endTs = frames[frames.length - 1].timestamp;
    if (target >= endTs) {
      this.emit(frames.length - 1);
      if (this.loop) { this.cursor = 0; this.startClock = performance.now(); }
      else { this.finished = true; if (this.animId) { cancelAnimationFrame(this.animId); this.animId = 0; } }
      return;
    }
    this.emit(this.cursor);
  };

  emit(index) {
    const clip = this.clip;
    if (!clip) return;
    const frame = clip.frames[index];
    if (!frame) return;
    this.onFrame(frameToResult(frame, this.providerId), frame.timestamp);
  }
}

export function playbackEnded(pb) {
  return pb["finished"] === true && !pb.isPlaying;
}
